import {readableCode} from './code-tools.js';
import {highlightCode,procedureTools} from './abap-highlight.js';
import {explainTerms} from './plain-language.js';
export const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=u=>{try{const v=new URL(u);return ['https:','http:'].includes(v.protocol)?v.href:''}catch{return ''}};
function link(url,label){const target=safeURL(url),id=target.match(/(?:app\.notion\.com\/p\/|notion\.so\/)([a-f0-9]{32})/)?.[1];const own=target.match(/^https:\/\/abap-workbench-dohyun\.doyhun\.chatgpt\.site\/#docs\/([a-zA-Z0-9_-]+)$/)?.[1];return own?`<a href="#docs/${escape(own)}" data-doc-link="${escape(own)}">${label||'연결 문서'}</a>`:id?`<a href="#docs/notion-${id}" data-doc-link="notion-${id}">${label||'연결 문서'}</a>`:target?`<a href="${escape(target)}" target="_blank" rel="noopener noreferrer">${label||'원본 열기'}</a>`:label;}
export function inline(text){const tokens=[];const token=html=>{tokens.push(html);return '\u0001'+(tokens.length-1)+'\u0002'};let v=String(text).replace(/`([^`]+)`/g,(_,t)=>token('<code>'+escape(t)+'</code>')).replace(/!\[([^\]]*)\]\(([^\s)]+)(?:\s+"[^"]*")?\)/g,(_,a,u)=>token(link(u,'이미지: '+escape(a||'원본에서 보기')))).replace(/\[([^\]]+)\]\(([^\s)]+)\)/g,(_,l,u)=>token(link(u,escape(l))));v=escape(v).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>');v=explainTerms(v);return v.replace(/\u0001(\d+)\u0002/g,(_,n)=>tokens[n]);}
export function renderDocument(body,blocks,context={}){const pictures=[];const image=(ref,alt='원문 캡처')=>{const asset=context.images?.[ref];const path=asset?.path||(/^\.\/assets\/github-fi\/[a-f0-9]+\.png$/.test(ref)?ref.slice(2):'');const local=/^assets\/(?:notion\/[a-f0-9]+\.webp|github-fi\/[a-f0-9]+\.png)$/.test(path);const result=local?`<figure class="source-image"><a href="./${escape(path)}" target="_blank" rel="noopener noreferrer"><img src="./${escape(path)}" alt="${escape(alt||'원문 캡처')}" loading="lazy" decoding="async" ${asset?.width?`width="${Number(asset.width)}" height="${Number(asset.height)}"`:''}></a><figcaption>원본 해상도 캡처 · 눌러서 크게 보기</figcaption></figure>`:link(context.url||ref,'이미지 원문에서 보기');pictures.push(result);return '\n@@IMAGE:'+(pictures.length-1)+'@@\n';};const codeBlocks=[];let prepared=String(body).replace(/^[ \t]*(`{3,})([^\n]*)\n([\s\S]*?)^[ \t]*\1[ \t]*$/gm,(_,fence,lang,code)=>{const idx=blocks.push({lang:lang.trim(),code:code.replace(/\n$/,'')})-1;codeBlocks.push(idx);return '\n@@CODE:'+idx+'@@\n'});
prepared=prepared.replace(/!\[([^\]]*)\]\(([^\s)]+)(?:\s+"[^"]*")?\)/g,(_,alt,ref)=>image(ref,alt)).replace(/<image\b[^>]*url="([^"]+)"[^>]*>([\s\S]*?)<\/image>/g,(_,ref,alt)=>image(ref,alt.replace(/<[^>]+>/g,''))).replace(/<mention-page\b[^>]*url="([^"]+)"[^>]*>([^<]+)<\/mention-page>/g,(_,u,t)=>`[${t}](${u})`).replace(/<\/?(?:callout|columns|column|details|summary)\b[^>]*>/g,'\n');
prepared=prepared.replace(/<page\b[^>]*url="([^"]+)"[^>]*>([\s\S]*?)<\/page>/g,(_,u,t)=>`\n[${t||'하위 문서'}](${u})\n`).replace(/<mention-page\b[^>]*url="([^"]+)"[^>]*\/?>(?:<\/mention-page>)?/g,(_,u)=>`[${context.linkTitles?.['notion-'+u.match(/[a-f0-9]{32}/)?.[0]]||'연결 문서'}](${u})`).replace(/<image\b[^>]*url="([^"]+)"[^>]*>([\s\S]*?)<\/image>/g,(_,u,t)=>`\n[이미지: ${t.replace(/<[^>]+>/g,'')||'원본에서 보기'}](${u})\n`).replace(/<empty-block\s*\/>/g,'\n').replace(/<table_of_contents\s*\/>/g,'').replace(/<table[^>]*>/g,'\n@@TABLE@@\n').replace(/<\/table>/g,'\n@@ENDTABLE@@\n').replace(/<tr[^>]*>/g,'\n@@ROW@@\n').replace(/<\/tr>/g,'\n@@ENDROW@@\n').replace(/<td[^>]*>([\s\S]*?)<\/td>/g,(_,t)=>'@@CELL:'+JSON.stringify(t)+'@@\n');
let out='',list='',table=false,row=false;let paragraph=[];const flush=()=>{if(paragraph.length){out+='<p>'+inline(paragraph.join(' '))+'</p>';paragraph=[]}};const endList=()=>{if(list){out+='</'+list+'>';list=''}};
for(const raw of prepared.split('\n')){const line=raw.trim();if(/^@@IMAGE:\d+@@$/.test(line)){flush();endList();out+=pictures[Number(line.match(/\d+/)[0])];continue;}if(/^@@CODE:\d+@@$/.test(line)){flush();endList();const idx=Number(line.match(/\d+/)[0]),b=blocks[idx];out+=`<section class="doc-code" data-code-block="${idx}"><header><span>${escape(b.lang||'코드')} · 전체 ${b.code.split('\n').length}줄 · 원문 주석 포함</span><div><button data-archive-fold aria-expanded="true">접기</button><button data-archive-copy="${idx}">주석 포함 복사</button><button data-archive-download="${idx}">${/^(abap|sql|cds)?$/i.test(b.lang)?'HTML 저장':'원본 파일 저장'}</button></div></header>${/^(abap|sql|cds)?$/i.test(b.lang)?procedureTools(b.code,idx):''}<pre class="abap-code" tabindex="0"><code>${/^(abap|sql|cds)?$/i.test(b.lang)?highlightCode(readableCode(b.code)):escape(b.code)}</code></pre></section>`;continue;}if(line==='@@TABLE@@'){flush();endList();out+='<div class="doc-table-scroll"><table>';table=true;continue;}if(line==='@@ENDTABLE@@'){out+='</table></div>';table=false;continue;}if(line==='@@ROW@@'){out+='<tr>';row=true;continue;}if(line==='@@ENDROW@@'){out+='</tr>';row=false;continue;}if(line.startsWith('@@CELL:')&&line.endsWith('@@')){let v='';try{v=JSON.parse(line.slice(7,-2))}catch{}out+='<td>'+inline(v)+'</td>';continue;}if(!line){flush();endList();continue;}if(/^#{1,6}\s/.test(line)){flush();endList();const level=Math.min(4,line.match(/^#+/)[0].length+1),text=line.replace(/^#+\s*/,''),id='section-'+blocks.headings.length;blocks.headings.push({id,text});out+=`<h${level} id="${id}">${inline(text)}</h${level}>`;continue;}if(/^[-*]\s|^\d+\.\s/.test(line)){flush();const type=/^\d/.test(line)?'ol':'ul';if(type!==list){endList();out+='<'+type+'>';list=type}out+='<li>'+inline(line.replace(/^([-*]|\d+\.)\s+/,''))+'</li>';continue;}if(line.startsWith('>')){flush();endList();out+='<blockquote>'+inline(line.replace(/^>\s?/,''))+'</blockquote>';continue;}if(/^<[^>]+>/.test(line)){flush();out+='<p class="doc-unrendered">'+escape(line)+'</p>';continue;}if(/^\|/.test(line)){flush();endList();const cells=line.split('|').slice(1,-1).map(s=>s.trim());if(cells.every(s=>/^:?-+:?$/.test(s)))continue;out+='<div class="doc-markdown-row">'+cells.map(c=>'<span>'+inline(c)+'</span>').join('')+'</div>';continue;}paragraph.push(line);}
flush();endList();if(row)out+='</tr>';if(table)out+='</table></div>';return out;}
